import 'dart:async';
import 'dart:convert';
import 'package:http/http.dart' as http;
import '../../../core/config/app_environment.dart';
import '../../../core/errors/app_exception.dart';
class MoneyAccount{const MoneyAccount({required this.id,required this.name,required this.type});final int id;final String name,type;factory MoneyAccount.fromJson(Map<String,dynamic> j)=>MoneyAccount(id:(j['id'] as num).toInt(),name:j['name']?.toString()??'',type:j['account_type']?.toString()??'CASH');}
class MoneyCategory{const MoneyCategory({required this.id,required this.name,required this.type});final int id;final String name,type;factory MoneyCategory.fromJson(Map<String,dynamic> j)=>MoneyCategory(id:(j['id'] as num).toInt(),name:j['name']?.toString()??'',type:j['category_type']?.toString()??'EXPENSE');}
class MoneyTransaction{const MoneyTransaction({required this.id,required this.accountId,required this.categoryId,required this.transferAccountId,required this.type,required this.amount,required this.description,required this.date});final int id,accountId;final int? categoryId,transferAccountId;final String type,description;final double amount;final DateTime date;factory MoneyTransaction.fromJson(Map<String,dynamic> j)=>MoneyTransaction(id:(j['id'] as num).toInt(),accountId:(j['account_id'] as num).toInt(),categoryId:(j['category_id'] as num?)?.toInt(),transferAccountId:(j['transfer_account_id'] as num?)?.toInt(),type:j['transaction_type']?.toString()??'EXPENSE',amount:(j['amount'] as num).toDouble(),description:j['description']?.toString()??'',date:DateTime.parse(j['transaction_date'].toString()).toLocal());}
class MoneyApi{
 MoneyApi({required this.config,http.Client? client}):_client=client??http.Client();final AppEnvironmentConfig config;final http.Client _client;static const _timeout=Duration(seconds:15);
 Map<String,String> _h(String t)=>{'Accept':'application/json','Authorization':'Bearer $t'};Uri _u(String p){final b=Uri.parse(config.apiBaseUrl);return b.replace(path:b.path+p);}
 Future<http.Response> _r(Future<http.Response> Function() f)async{try{return await f().timeout(_timeout);}on TimeoutException{throw const NetworkException('The server took too long to respond.');}catch(e){if(e is AppException)rethrow;throw const NetworkException('Unable to reach the server.');}}
 dynamic _d(http.Response r){dynamic d;try{d=jsonDecode(r.body);}catch(_){throw ApiException('Invalid server response.',statusCode:r.statusCode);}if(r.statusCode<200||r.statusCode>=300)throw ApiException(d is Map?d['detail']?.toString()??'Money request failed.':'Money request failed.',statusCode:r.statusCode);return d;}
 Future<List<MoneyAccount>> accounts(String t)async{final r=await _r(()=>_client.get(_u('/api/v1/accounts'),headers:_h(t)));final d=_d(r) as List;return d.map((x)=>MoneyAccount.fromJson(Map<String,dynamic>.from(x as Map))).toList();}
 Future<List<MoneyCategory>> categories(String t)async{final r=await _r(()=>_client.get(_u('/api/v1/categories'),headers:_h(t)));final d=_d(r) as List;return d.map((x)=>MoneyCategory.fromJson(Map<String,dynamic>.from(x as Map))).toList();}
 Future<List<MoneyTransaction>> list(String t)async{final r=await _r(()=>_client.get(_u('/api/v1/transactions'),headers:_h(t)));final d=_d(r) as List;return d.map((x)=>MoneyTransaction.fromJson(Map<String,dynamic>.from(x as Map))).toList();}
 Future<void> create(String t,{required int accountId,int? categoryId,int? transferAccountId,required String type,required double amount,String? description,required DateTime date})async{final r=await _r(()=>_client.post(_u('/api/v1/transactions'),headers:{..._h(t),'Content-Type':'application/json'},body:jsonEncode({'account_id':accountId,'category_id':categoryId,'transfer_account_id':transferAccountId,'transaction_type':type,'amount':amount,'description':description,'transaction_date':date.toUtc().toIso8601String()})));_d(r);}
 Future<void> update(String t,int id,{required int accountId,int? categoryId,int? transferAccountId,required String type,required double amount,String? description,required DateTime date})async{final r=await _r(()=>_client.patch(_u('/api/v1/transactions/'+id.toString()),headers:{..._h(t),'Content-Type':'application/json'},body:jsonEncode({'account_id':accountId,'category_id':categoryId,'transfer_account_id':transferAccountId,'transaction_type':type,'amount':amount,'description':description,'transaction_date':date.toUtc().toIso8601String()})));_d(r);}
 Future<void> remove(String t,int id)async{final r=await _r(()=>_client.delete(_u('/api/v1/transactions/'+id.toString()),headers:_h(t)));_d(r);}
}